// 金额的呈现：**唯一出口**（AGENTS.md 的纪律二）。
//
// TODO：今天是把分直接当元印出去了（历史上留下的 bug），要改成「分 / 100，保留两位」。
export function yuan(cents: number): string {
  return String(cents)
}

export function fen(yuanText: string): number {
  return Math.round(Number(yuanText) * 100)
}

// 求和那一类纯函数。

export function total(xs: readonly number[]): number {
  let sum = 0
  for (const x of xs) sum += x
  return sum
}

export function max(xs: readonly number[]): number {
  return xs.reduce((a, b) => (b > a ? b : a), Number.NEGATIVE_INFINITY)
}

// 上一版的实现：它把分当元印，与 src/format.ts 的 TODO 是同一件事。
// 已经没有调用点（grep 过 src/）——按 AGENTS.md 的纪律三，这一份该删掉。
module.exports = { yuan: (cents) => String(cents) }
